$lang['map_introtext1'] = 'खालील नकाशा शोध निकालातील भू-स्थान असलेल्या संसाधनांना दर्शवितो. मार्करचा रंग संसाधन प्रकार किंवा सानुकूल मेटाडेटा फील्ड (नकाशाच्या खालील की) नुसार सेट केला जातो. जेव्हा मार्कर्स एकमेकांवर ओव्हरप्रिंट होतील, तेव्हा हिरव्या रंगाचा क्लस्टरिंग वापरला जातो ज्यामध्ये क्लस्टर केलेल्या मार्कर्सची संख्या दर्शविली जाते, झूम इन करा किंवा क्लस्टरवर डबल क्लिक करा. एखाद्या मार्करवर क्लिक केल्यास त्या संसाधनासाठी प्रीव्ह्यू प्रतिमा असलेले पॉपअप लोड होते. प्रीव्ह्यू प्रतिमेवर क्लिक केल्यास त्या संसाधनासाठी विंडो लोड होते. एखाद्या मार्करवर होवर केल्यास भू-निर्देशांक दिसतात. वरच्या उजव्या नकाशा बटणाचा वापर करून बेसमॅप बदला. खालील डाव्या नकाशा बटणाचा वापर करून नकाशा PNG फाईल म्हणून जतन करा.';
$lang['edit_map_introtext'] = 'इच्छित नकाशा दृश्य पॅन आणि झूम करा, नंतर संसाधन स्थान मार्कर शोधण्यासाठी नकाशावर क्लिक करा. नवीनतम भू-स्थान सेव्ह करण्यासाठी सेव्ह बटण वापरा आणि नंतर \'संसाधन संपादित करा किंवा संग्रह भू-स्थानावर परत जा\' क्लिक करा. विशिष्ट स्थान किंवा भौगोलिक वैशिष्ट्य शोधण्यासाठी वरच्या उजव्या शोध बटणाचा वापर करा. वरच्या उजव्या नकाशा स्तर बटणाचा वापर करून बेसमॅप बदला. खालील डाव्या नकाशा बटणाचा वापर करून नकाशा PNG फाईल म्हणून जतन करा.';
