$lang['collection_email__introtextthemeshare'] = 'खालील फॉर्म पूर्ण करा जेणेकरून या वैशिष्ट्यीकृत संग्रह श्रेणीतल्या वैशिष्ट्यीकृत संग्रहांना ईमेल करता येईल. प्राप्तकर्त्यांना प्रत्येक वैशिष्ट्यीकृत संग्रहाच्या दुव्यांसह ईमेल मिळेल.';
$lang['collection_manage__findpublic'] = 'सार्वजनिक संग्रह म्हणजे प्रणाली वापरकर्त्यांनी मोठ्या प्रमाणावर उपलब्ध केलेले संसाधन गट. सार्वजनिक संग्रह शोधण्यासाठी संग्रह आयडी, किंवा संग्रह नाव किंवा वापरकर्तानावाचा काही भाग टाका. त्यांना आपल्या संग्रह यादीत जोडा आणि संसाधने वापरा.';
$lang['collection_manage__introtext'] = 'संसाधने एकत्र करून आपले काम संघटित आणि व्यवस्थापित करा. आपल्या कामाच्या पद्धतीनुसार \'संग्रह\' तयार करा. आपण स्वतंत्रपणे काम करत असलेल्या प्रकल्पांखाली संसाधने गटबद्ध करू शकता, प्रकल्प टीममध्ये संसाधने सामायिक करू शकता किंवा फक्त आपल्या आवडत्या संसाधनांना एका ठिकाणी ठेवू शकता. आपल्या यादीतील सर्व संग्रह स्क्रीनच्या तळाशी \'माझे संग्रह\' पॅनेलमध्ये दिसतील.';
$lang['collection_manage__newcollection'] = 'नवीन संग्रह तयार करण्यासाठी, एक लहान नाव टाका.';
$lang['collection_public__introtext'] = 'सार्वजनिक संग्रह इतर वापरकर्त्यांनी तयार केलेले आहेत.';
