$lang['oj_recreate_previews_refs_help'] = 'या पर्यायामुळे कोणते संदर्भ (संसाधन किंवा संग्रह संदर्भ) प्रक्रिया साठी वापरले जातील हे नियंत्रित होते. वैध इनपुटमध्ये कॉमा-वेगळे यादी, श्रेणी आणि वाइल्डकार्ड्स समाविष्ट आहेत उदा. * सर्व संदर्भ प्रक्रिया करेल, 1-100 पहिल्या 100 संदर्भ प्रक्रिया करेल, 101-* संदर्भ 101 पासून पुढे प्रक्रिया करेल आणि 1,3,5 संदर्भ 1, 3 आणि 5 प्रक्रिया करेल. हे एकत्र करून नेमके आवश्यक संदर्भ लक्ष्य करता येतात उदा. 1,5-10,15-* हे 1, 5 ते 10 आणि 15 पासून पुढे लक्ष्य करेल.';
$lang['oj_recreate_previews_use_existing_help'] = 'हा पर्याय सेट केल्यास संसाधनांवर मॅन्युअली बदललेली कोणतीही पूर्वावलोकने जपण्याचा प्रयत्न केला जाईल. वापरले नाही तर मॅन्युअली अपलोड केलेली पूर्वावलोकने मूळ फाइलमधून तयार केलेल्या पूर्वावलोकनांनी बदलली जातील.';
$lang['oj_recreate_previews_video_update_help'] = 'हा पर्याय सेट केल्यास सध्याच्या कॉन्फिगर केलेल्या \'$ffmpeg_preview_extension\' विस्ताराशी जुळणारे नसलेले व्हिडिओ अद्यतनित केले जातील. हा सेटिंग बदलल्यावर नवीन पूर्वावलोकन तयार करणे आवश्यक असलेल्या संसाधनांवर लक्ष केंद्रित करण्यासाठी उपयुक्त आहे.';
