$lang['oj_exif_data_field_refs_help'] = 'हे त्या फील्ड संदर्भ आहेत ज्यासाठी तुम्हाला EXIF डेटा काढायचा आहे. या फील्डमध्ये "Exiftool field" कॉन्फिगर केलेले असावे. कॉमा-वेगळ्या यादीचा वापर करून फील्ड निर्दिष्ट करता येतात उदा. 1,3,5.';
$lang['oj_exif_data_collection_refs_help'] = 'हा पर्याय सेट केल्यास फक्त सूचीबद्ध संग्रहांतील संसाधने अद्यतनित केली जातील. जर कोणतेही संग्रह निर्दिष्ट केले नाहीत तर सर्व योग्य संसाधनांसाठी EXIF डेटा अद्यतनित केला जाईल. संग्रह कॉमा-वेगळ्या यादी आणि श्रेणी वापरून निर्दिष्ट करता येतात उदा. 100,105,110-115';
