$lang['research_request__introtext'] = 'तुमच्या प्रकल्पांसाठी सर्वोत्तम संसाधने शोधण्यात मदत करण्यासाठी आमचे व्यावसायिक संशोधक उपलब्ध आहेत. तुमच्या निकषांनुसार अचूक मदत करता यावी, यासाठी हा फॉर्म शक्य तितक्या सविस्तरपणे भरा. <br /><br />संशोधन पथकातील एका सदस्याला तुमची विनंती नेमून दिली जाईल. या प्रक्रियेदरम्यान आम्ही ईमेलद्वारे तुमच्या संपर्कात राहू. संशोधन पूर्ण झाल्यावर, आम्ही सुचवलेल्या सर्व संसाधनांची लिंक तुम्हाला ईमेलने पाठवली जाईल.  ';
$lang['search_advanced__introtext'] = '<strong>शोधासाठी टिप</strong><br />रिक्त ठेवलेला किंवा निवडचिन्ह न केलेला कोणताही विभाग शोधात त्या विभागातील सर्व संज्ञा समाविष्ट करेल. उदाहरणार्थ, तुम्ही देशांचे सर्व पर्याय रिक्त ठेवल्यास, शोधात सर्व देशांतील परिणाम दिसतील. तुम्ही फक्त \'अल्जेरिया\' निवडल्यास, परिणामांमध्ये फक्त \'अल्जेरिया\'मधील संसाधने दिसतील. ';
$lang['team_research__introtext'] = '\'संशोधन विनंत्या\' आयोजित करा आणि व्यवस्थापित करा. <br /><br />विनंतीचा तपशील तपासण्यासाठी आणि संशोधन पथकातील सदस्याला संशोधन नेमून देण्यासाठी \'संशोधन संपादित करा\' निवडा. \'संपादन\' स्क्रीनमध्ये संग्रहाचा ID टाकून पूर्वीच्या संग्रहावर आधारित संशोधन विनंती तयार करता येते. <br /><br />संशोधन विनंती नेमून दिल्यानंतर, \'डीफॉल्ट संग्रह\' पॅनेलमध्ये संशोधन विनंती जोडण्यासाठी \'संग्रह संपादित करा\' निवडा. त्यानंतर नेहमीच्या साधनांचा वापर करून संशोधनात संसाधने जोडता येतात. <br /><br />संशोधन पूर्ण झाल्यावर, \'संशोधन संपादित करा\' निवडा, स्थिती पूर्ण अशी बदला आणि संशोधनाची विनंती करणाऱ्या वापरकर्त्याला आपोआप ईमेल पाठवला जाईल. ईमेलमध्ये संशोधनाची लिंक असेल आणि ते वापरकर्त्याच्या \'डीफॉल्ट संग्रह\' पॅनेलमध्येही आपोआप जोडले जाईल.';
$lang['themes__manage'] = 'ऑनलाइन उपलब्ध वैशिष्ट्यीकृत संग्रह आयोजित करा आणि संपादित करा. वैशिष्ट्यीकृत संग्रहांना विशेष प्रोत्साहन दिलेले असते. <br /><br /> <strong>1 वैशिष्ट्यीकृत संग्रहाखाली नवीन नोंद तयार करण्यासाठी - संग्रह तयार करा</strong><br /> मुख्य वरच्या मेनूमधून <strong>माझे संग्रह</strong> निवडा आणि नवीन <strong>सार्वजनिक</strong> संग्रह तयार करा. सेटअपदरम्यान वैशिष्ट्यीकृत संग्रहाचे नाव समाविष्ट करण्याचे लक्षात ठेवा. संग्रहाला सध्याच्या वैशिष्ट्यीकृत संग्रहाखाली गटबद्ध करण्यासाठी त्याचे विद्यमान नाव वापरा (ते अगदी तसेच टाइप करा) किंवा नवीन वैशिष्ट्यीकृत संग्रह तयार करण्यासाठी नवीन शीर्षक निवडा. वापरकर्त्यांना वैशिष्ट्यीकृत संग्रहांमधून संसाधने जोडण्याची किंवा काढण्याची परवानगी कधीही देऊ नका. <br /> <br /><strong>2 वैशिष्ट्यीकृत संग्रहाखालील विद्यमान नोंदीतील मजकूर संपादित करण्यासाठी</strong><br /> <strong>संग्रह संपादित करा</strong> निवडा. त्या संग्रहातील घटक स्क्रीनच्या तळाशी असलेल्या <strong>माझे संग्रह</strong> पॅनेलमध्ये दिसतील. संसाधने संपादित करण्यासाठी, काढण्यासाठी किंवा जोडण्यासाठी नेहमीची साधने वापरा. <br /> <br /><strong>3 वैशिष्ट्यीकृत संग्रहाचे नाव बदलण्यासाठी किंवा संग्रह दुसऱ्या वैशिष्ट्यीकृत संग्रहाखाली हलवण्यासाठी</strong><br /> <strong>गुणधर्म संपादित करा</strong> निवडा आणि वैशिष्ट्यीकृत संग्रहाची श्रेणी किंवा संग्रहाचे नाव संपादित करा. संग्रहाला सध्याच्या वैशिष्ट्यीकृत संग्रहाखाली गटबद्ध करण्यासाठी त्याचे विद्यमान नाव वापरा (ते अगदी तसेच टाइप करा) किंवा नवीन वैशिष्ट्यीकृत संग्रह तयार करण्यासाठी नवीन शीर्षक निवडा. <br /> <br /><strong>4 वैशिष्ट्यीकृत संग्रहातून संग्रह काढण्यासाठी</strong><br /> <strong>गुणधर्म संपादित करा</strong> निवडा आणि वैशिष्ट्यीकृत संग्रहाच्या श्रेणीच्या चौकटीतील मजकूर हटवा. ';
$lang['notify_resource_change_email'] = 'तुम्ही मागील [days] दिवसांत डाउनलोड केलेल्या संसाधनात बदल करण्यात आला आहे. संसाधन पाहण्यासाठी खालील लिंकवर क्लिक करा.<br /><br /><a href=\'[url]\'>[url]</a>';
