$lang['done__user_password_link_sent'] = 'तुमचा ईमेल पत्ता वैध खात्याशी संबंधित असल्याचे आढळल्यास, पासवर्ड रीसेट करण्याची लिंक असलेला ईमेल पाठवण्यात आला आहे.<br /><br /> ईमेल न मिळाल्यास आणि तुमचे खाते वैध असल्याचा तुम्हाला विश्वास असल्यास, तुमच्या प्रणाली प्रशासकाशी संपर्क साधण्यापूर्वी ईमेल फिल्टर तपासा.';

$lang['information-geomapping'] = 'या फील्डमध्ये भू-स्थानिक माहिती अक्षांश, रेखांश किंवा दोन्ही स्वरूपात संग्रहित करा.<br />फक्त एकाच फील्डला दोन्ही किंवा एक फील्डला अक्षांश आणि दुसऱ्या फील्डला रेखांश म्हणून सेट करता येईल.<br />हे फक्त एक ओळीच्या मजकूर फील्डसाठी उपलब्ध आहे.';
$lang['accountdoesnotexist'] = 'हा वापरकर्ता खाते अस्तित्वात नाही.<br />जर आपण वापरकर्ता संदेश विभागातील लिंकवरून या पृष्ठावर आला असाल, तर कृपया लक्षात घ्या की दुसऱ्या प्रशासकाने कदाचित आधीच खाते विनंती हाताळली असेल आणि हे खाते काढून टाकले असेल.';
$lang['contactsheetintrotext'] = 'कृपया आपल्या संपर्क पत्रक PDF साठी आपण इच्छित कॉन्फिगरेशन पर्याय निवडा. पर्याय बदलल्यावर पूर्वावलोकन आपोआप अद्ययावत होईल. जर आपण निवडलेल्या मेटाडेटा फील्ड किंवा संग्रहातील संसाधनांची क्रमवारी बदलली तर "पूर्वावलोकन अद्ययावत करा" बटण दाबून अद्ययावत करा.<br />तयार झाल्यावर, "निर्माण करा" दाबा आणि आपले संपर्क पत्रक PDF डाउनलोड करा.';
$lang['exportdata-instructions'] = 'हे आपल्या प्रणालीतील कॉन्फिगरेशन डेटा निर्यात करेल ज्याचा वापर समस्या निवारणासाठी होतो. सर्व डेटा (फील्ड पर्याय, वापरकर्तानावे, ईमेल आणि मेटाडेटा इ.) आपल्या सर्व्हर प्रशासकाच्या परवानगीशिवाय अस्पष्ट केला जाईल.</br>आपण निर्यात करू इच्छित माहिती निवडा आणि \'निर्यात करा\' क्लिक करा. एक ऑफलाइन काम तयार होईल आणि डाउनलोड तयार झाल्यावर आपल्याला सूचना मिळेल.';
$lang['tagcloudtext'] = 'लोकांनी कोणत्या मेटाडेटा संज्ञा वापरून संसाधने टॅग केली आहेत? जास्त वापरलेली संज्ञा मोठ्या आकारात दिसेल.<br /><br />खालील कोणत्याही संज्ञेवर क्लिक करून शोध चालवू शकता.';
